const bases={brut:'gross',gross:'gross',t1:'t1',tranche1:'t1',brutplafonne:'t1',t2:'t2',tranche2:'t2',cap4:'cap4',quatreplafonds:'cap4',cap8:'cap8',huitplafonds:'cap8',csg:'csg',csgcrds:'csg'};
